struct Tracer {
    explicit Tracer(int);
};
Tracer a{1};   // 可以
Tracer b = 1;  // 不可以：拷贝初始化不看 explicit 构造

std::string a = "hi";
std::string b = std::move(a);
// std::move(a) 只是把左值变成将亡值。
// 真正把缓冲区交出去的是 string 的移动构造。

int a = 1;
int& r = a;   // r 就是 a
r = 2;        // 改的是 a
// int& s;    // 不可以：引用没有「先声明再绑定」

Buf b = std::move(a);
// b 拿走 a 的缓冲区。
// a 仍是一个活着的 Buf，可以析构、可以赋新值，
// 不要再假设它里面还有原来的数据。

auto p = std::make_unique<int>(1);
auto q = std::move(p);
// p 不再拥有那块 int，q 析构时释放。
// auto r = q;  // 不可以：独占指针没有拷贝
